function bakedFor(steam_t, soak_days, cutoff, spm, stroke_in, p_wellhead_kgf_cm2, float_policy){
  /* rev 13.1: a baked match now requires EVERY control, including spm and
     float_policy -- before this fix spm/float_policy were ignored, so the
     12-SPM stress test (and any non-default "Rod-float response" pick)
     wrongly resolved to the 5-spm/VFD-hold baked reference series ("baked
     twin output" instead of the honest "in-browser approximation"), and
     because it counted as "baked" it was published to the Overview as the
     run on the books. See dashboard/README.md §6 and TIER1_PROGRESS_LOG.md
     re-score item 7. */
  const near = (a, b, eps) => (a === undefined || b === undefined) ? true : Math.abs(a - b) <= eps;
  const sameStr = (a, b) => (a === undefined || b === undefined) ? true : a === b;
  for (const key of Object.keys(BAKED)){
    const b = BAKED[key];
    if (near(steam_t, b.inputs.steam_t, 1) && near(soak_days, b.inputs.soak_days, 0.01) &&
        near(cutoff, b.inputs.cutoff, 0.01) &&
        near(spm, b.inputs.spm, 0.05) &&
        near(stroke_in, b.inputs.stroke_in, 0.5) &&
        near(p_wellhead_kgf_cm2, b.inputs.p_wellhead_kgf_cm2, 0.5) &&
        sameStr(float_policy, b.inputs.float_policy)) return b;
  }
  return null;
}
